/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'USUUSUARIO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuUsuario1.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuUsuario1) EndIf Case &DynamicFiltersSelector1 = !'USUNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuNome1.FromString(&GridStateDynamicFilter.Value) If not &usuNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuNome1) EndIf Case &DynamicFiltersSelector1 = !'USUGUID' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuGUID1.FromString(&GridStateDynamicFilter.Value) If not &usuGUID1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuGUID1) EndIf Case &DynamicFiltersSelector1 = !'USUEMAIL' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &usuEmail1.FromString(&GridStateDynamicFilter.Value) If not &usuEmail1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuEmail1) EndIf Case &DynamicFiltersSelector1 = !'PREFCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prefCodigo1.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Prefeitura", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &prefCodigo1 EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'USUUSUARIO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuUsuario2.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuUsuario2) EndIf Case &DynamicFiltersSelector2 = !'USUNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuNome2.FromString(&GridStateDynamicFilter.Value) If not &usuNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuNome2) EndIf Case &DynamicFiltersSelector2 = !'USUGUID' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuGUID2.FromString(&GridStateDynamicFilter.Value) If not &usuGUID2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuGUID2) EndIf Case &DynamicFiltersSelector2 = !'USUEMAIL' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &usuEmail2.FromString(&GridStateDynamicFilter.Value) If not &usuEmail2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuEmail2) EndIf Case &DynamicFiltersSelector2 = !'PREFCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prefCodigo2.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Prefeitura", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &prefCodigo2 EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'USUUSUARIO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuUsuario3.FromString(&GridStateDynamicFilter.Value) If not &usuUsuario3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuUsuario3) EndIf Case &DynamicFiltersSelector3 = !'USUNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuNome3.FromString(&GridStateDynamicFilter.Value) If not &usuNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuNome3) EndIf Case &DynamicFiltersSelector3 = !'USUGUID' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuGUID3.FromString(&GridStateDynamicFilter.Value) If not &usuGUID3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Usuário GAM", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuGUID3) EndIf Case &DynamicFiltersSelector3 = !'USUEMAIL' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &usuEmail3.FromString(&GridStateDynamicFilter.Value) If not &usuEmail3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Email", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&usuEmail3) EndIf Case &DynamicFiltersSelector3 = !'PREFCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prefCodigo3.FromString(&GridStateDynamicFilter.Value) If not &prefCodigo3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Prefeitura", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &prefCodigo3 EndIf EndCase EndIf EndIf EndIf If not (&TFusuCodigo.IsEmpty() AND &TFusuCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFusuCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFusuCodigo_To EndIf If not (&TFprefCodigo.IsEmpty() AND &TFprefCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Prefeitura") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFprefCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFprefCodigo_To EndIf If not (&TFusuUsuario_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Usuário") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuUsuario_Sel) Else If not (&TFusuUsuario.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Usuário") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuUsuario) EndIf EndIf If not (&TFusuNome_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuNome_Sel) Else If not (&TFusuNome.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuNome) EndIf EndIf If not (&TFusuCargo.IsEmpty() AND &TFusuCargo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Cargo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFusuCargo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFusuCargo_To EndIf If not (&TFusuEmail_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Email") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuEmail_Sel) Else If not (&TFusuEmail.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Email") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFusuEmail) EndIf EndIf If not (&TFusuStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Situacao") &i = 1 For &TFusuStatus_Sel in &TFusuStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf do Case Case &TFusuStatus_Sel.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Ativo"
Case &TFusuStatus_Sel.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += "Inativo"
EndCase &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsusuariosWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsusuariosWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsusuarios order usuUsuario when &OrderedBy = 1 AND &OrderedDsc = False order (usuUsuario) when &OrderedBy = 1 AND &OrderedDsc = True order usuCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (usuCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) when &OrderedBy = 3 AND &OrderedDsc = True order usuNome when &OrderedBy = 4 AND &OrderedDsc = False order (usuNome) when &OrderedBy = 4 AND &OrderedDsc = True order usuCargo when &OrderedBy = 5 AND &OrderedDsc = False order (usuCargo) when &OrderedBy = 5 AND &OrderedDsc = True order usuEmail when &OrderedBy = 6 AND &OrderedDsc = False order (usuEmail) when &OrderedBy = 6 AND &OrderedDsc = True order usuStatus when &OrderedBy = 7 AND &OrderedDsc = False order (usuStatus) when &OrderedBy = 7 AND &OrderedDsc = True
using trnsusuariosWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &usuUsuario1, &usuNome1, &usuGUID1, &usuEmail1 , &prefCodigo1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &usuUsuario2, &usuNome2 , &usuGUID2, &usuEmail2, &prefCodigo2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &usuUsuario3, &usuNome3, &usuGUID3, &usuEmail3, &prefCodigo3, &TFusuCodigo , &TFusuCodigo_To, &TFprefCodigo, &TFprefCodigo_To, &TFusuUsuario, &TFusuUsuario_Sel, &TFusuNome , &TFusuNome_Sel, &TFusuCargo, &TFusuCargo_To, &TFusuEmail, &TFusuEmail_Sel, &TFusuStatus_Sels)
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'usuCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = usuCodigo Case &ColumnsSelector_Column.ColumnName = !'prefCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = prefCodigo Case &ColumnsSelector_Column.ColumnName = !'usuUsuario' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(usuUsuario) Case &ColumnsSelector_Column.ColumnName = !'usuNome' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(usuNome) Case &ColumnsSelector_Column.ColumnName = !'usuCargo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = usuCargo Case &ColumnsSelector_Column.ColumnName = !'usuEmail' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(usuEmail) Case &ColumnsSelector_Column.ColumnName = !'usuStatus' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = '' do Case Case usuStatus.ToString().Trim() = "A" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Ativo"
Case usuStatus.ToString().Trim() = "I" &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = "Inativo"
EndCase EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsusuariosWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"prefCodigo", '', !'Prefeitura', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuUsuario", '', !'Usuário', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuNome", '', !'Nome', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuCargo", '', !'Cargo', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuEmail", '', !'Email', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"usuStatus", '', !'Situacao', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsusuariosWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsusuariosWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsusuariosWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsusuariosWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFUSUCODIGO" &TFusuCodigo.FromString(&GridStateFilterValue.Value) &TFusuCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPREFCODIGO" &TFprefCodigo.FromString(&GridStateFilterValue.Value) &TFprefCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFUSUUSUARIO" &TFusuUsuario.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUUSUARIO_SEL" &TFusuUsuario_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUNOME" &TFusuNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUNOME_SEL" &TFusuNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUCARGO" &TFusuCargo.FromString(&GridStateFilterValue.Value) &TFusuCargo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFUSUEMAIL" &TFusuEmail.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUEMAIL_SEL" &TFusuEmail_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUSUSTATUS_SEL" &TFusuStatus_SelsJson = &GridStateFilterValue.Value &TFusuStatus_Sels.FromJson(&TFusuStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
